1	package org.jsoup.select;
2	
3	import org.jsoup.helper.Regex;
4	import org.jsoup.internal.StringUtil;
5	import org.jsoup.helper.Validate;
6	import org.jsoup.nodes.CDataNode;
7	import org.jsoup.nodes.Comment;
8	import org.jsoup.nodes.DataNode;
9	import org.jsoup.nodes.LeafNode;
10	import org.jsoup.nodes.Node;
11	import org.jsoup.nodes.TextNode;
12	import org.jsoup.parser.TokenQueue;
13	import org.jspecify.annotations.Nullable;
14	
15	import java.util.function.Function;
16	import java.util.regex.Matcher;
17	import java.util.regex.Pattern;
18	
19	import static org.jsoup.select.StructuralEvaluator.ImmediateParentRun;
20	import static org.jsoup.internal.Normalizer.normalize;
21	
22	/**
23	 * Parses a CSS selector into an Evaluator tree.
24	 */
25	public class QueryParser implements AutoCloseable {
26	    private final static char[] Combinators = {'>', '+', '~'}; // ' ' is also a combinator, but found implicitly
27	    private final static String[] AttributeEvals = new String[]{"=", "!=", "^=", "$=", "*=", "~="};
28	    private final static char[] SequenceEnders = {',', ')'};
29	
30	    private final TokenQueue tq;
31	    private final String query;
32	    private boolean inNodeContext; // ::comment:contains should act on node value, vs element text
33	
34	    /**
35	     * Create a new QueryParser.
36	     * @param query CSS query
37	     */
38	    private QueryParser(String query) {
39	        Validate.notEmpty(query);
40	        query = query.trim();
41	        this.query = query;
42	        this.tq = new TokenQueue(query);
43	    }
44	
45	    /**
46	     Parse a CSS query into an Evaluator. If you are evaluating the same query repeatedly, it may be more efficient to
47	     parse it once and reuse the Evaluator.
48	
49	     @param query CSS query
50	     @return Evaluator
51	     @see Selector selector query syntax
52	     @throws Selector.SelectorParseException if the CSS query is invalid
53	     */
54	    public static Evaluator parse(String query) {
55	        try (QueryParser p = new QueryParser(query)) {
56	            return p.parse();
57	        } catch (IllegalArgumentException e) {
58	            throw new Selector.SelectorParseException(e.getMessage());
59	        }
60	    }
61	
62	    /**
63	     Parse the query. We use this simplified expression of the grammar:
64	     <pre>
65	     SelectorGroup   ::= Selector (',' Selector)*
66	     Selector        ::= [ Combinator ] SimpleSequence ( Combinator SimpleSequence )*
67	     SimpleSequence  ::= [ TypeSelector ] ( ID | Class | Attribute | Pseudo )*
68	     Pseudo           ::= ':' Name [ '(' SelectorGroup ')' ]
69	     Combinator      ::= S+         // descendant (whitespace)
70	     | '>'       // child
71	     | '+'       // adjacent sibling
72	     | '~'       // general sibling
73	     </pre>
74	
75	     See <a href="https://www.w3.org/TR/selectors-4/#grammar">selectors-4</a> for the real thing
76	     */
77	    Evaluator parse() {
78	        Evaluator eval = parseSelectorGroup();
79	        tq.consumeWhitespace();
80	        if (!tq.isEmpty())
81	            throw new Selector.SelectorParseException("Could not parse query '%s': unexpected token at '%s'", query, tq.remainder());
82	        return eval;
83	    }
84	
85	    Evaluator parseSelectorGroup() {
86	        // SelectorGroup. Into an Or if > 1 Selector
87	        Evaluator left = parseSelector();
88	        while (tq.matchChomp(',')) {
89	            Evaluator right = parseSelector();
90	            left = or(left, right);
91	        }
92	        return left;
93	    }
94	
95	    Evaluator parseSelector() {
96	        // Selector ::= [ Combinator ] SimpleSequence ( Combinator SimpleSequence )*
97	        tq.consumeWhitespace();
98	
99	        Evaluator left;
100	        if (tq.matchesAny(Combinators)) {
101	            // e.g. query is "> div"; left side is root element
102	            left = new StructuralEvaluator.Root();
103	        } else {
104	            left = parseSimpleSequence();
105	        }
106	
107	        while (true) {
108	            char combinator = 0;
109	            if (tq.consumeWhitespace())
110	                combinator = ' ';            // maybe descendant?
111	            if (tq.matchesAny(Combinators)) // no, explicit
112	                combinator = tq.consume();
113	            else if (tq.matchesAny(SequenceEnders)) // , - space after simple like "foo , bar"; ) - close of :has()
114	                break;
115	
116	            if (combinator != 0) {
117	                tq.consumeWhitespace();
118	                if (tq.matchesAny(Combinators) || tq.matchesAny(SequenceEnders) || tq.isEmpty())
119	                    // a dangling combinator (e.g. "div >", ":has(>)", or ":has(p, +)") is not a valid selector
120	                    throw new Selector.SelectorParseException(
121	                        "Could not parse query '%s': unexpected token at '%s'", query, tq.remainder());
122	                Evaluator right = parseSimpleSequence();
123	                left = combinator(left, combinator, right);
124	            } else {
125	                break;
126	            }
127	        }
128	        return left;
129	    }
130	
131	    Evaluator parseSimpleSequence() {
132	        // SimpleSequence ::= TypeSelector? ( Hash | Class | Pseudo )*
133	        Evaluator left = null;
134	        tq.consumeWhitespace();
135	
136	        // one optional type selector
137	        if (tq.matchesWord() || tq.matches("*|"))
138	            left = byTag();
139	        else if (tq.matchChomp('*'))
140	            left = new Evaluator.AllElements();
141	
142	        // zero or more subclasses (#, ., [)
143	        while(true) {
144	            Evaluator right = parseSubclass();
145	            if (right != null) {
146	                left = and(left, right);
147	            }
148	            else break; // no more simple tokens
149	        }
150	
151	        if (left == null)
152	            throw new Selector.SelectorParseException("Could not parse query '%s': unexpected token at '%s'", query, tq.remainder());
153	        return left;
154	    }
155	
156	    static Evaluator combinator(Evaluator left, char combinator, Evaluator right) {
157	        switch (combinator) {
158	            case '>':
159	                ImmediateParentRun run = left instanceof ImmediateParentRun ?
160	                    (ImmediateParentRun) left : new ImmediateParentRun(left);
161	                run.add(right);
162	                return run;
163	            case ' ':
164	                return and(new StructuralEvaluator.Ancestor(left), right);
165	            case '+':
166	                return and(new StructuralEvaluator.ImmediatePreviousSibling(left), right);
167	            case '~':
168	                return and(new StructuralEvaluator.PreviousSibling(left), right);
169	            default:
170	                throw new Selector.SelectorParseException("Unknown combinator '%s'", combinator);
171	        }
172	    }
173	
174	    @Nullable Evaluator parseSubclass() {
175	        //  Subclass: ID | Class | Attribute | Pseudo
176	        if      (tq.matchChomp('#'))    return byId();
177	        else if (tq.matchChomp('.'))    return byClass();
178	        else if (tq.matches('['))       return byAttribute();
179	        else if (tq.matchChomp("::"))   return parseNodeSelector(); // ::comment etc
180	        else if (tq.matchChomp(':'))    return parsePseudoSelector();
181	        else                            return null;
182	    }
183	
184	    /** Merge two evals into an Or. */
185	    static Evaluator or(Evaluator left, Evaluator right) {
186	        if (left instanceof CombiningEvaluator.Or) {
187	            ((CombiningEvaluator.Or) left).add(right);
188	            return left;
189	        }
190	        return new CombiningEvaluator.Or(left, right);
191	    }
192	
193	    /** Merge two evals into an And. */
194	    static Evaluator and(@Nullable Evaluator left, Evaluator right) {
195	        if (left == null) return right;
196	        if (left instanceof CombiningEvaluator.And) {
197	            ((CombiningEvaluator.And) left).add(right);
198	            return left;
199	        }
200	        return new CombiningEvaluator.And(left, right);
201	    }
202	
203	    private Evaluator parsePseudoSelector() {
204	        final String pseudo = tq.consumeCssIdentifier();
205	        switch (pseudo) {
206	            case "lt":
207	                return new Evaluator.IndexLessThan(consumeIndex());
208	            case "gt":
209	                return new Evaluator.IndexGreaterThan(consumeIndex());
210	            case "eq":
211	                return new Evaluator.IndexEquals(consumeIndex());
212	            case "has":
213	                return has();
214	            case "is":
215	                return is();
216	            case "contains":
217	                return contains(false);
218	            case "containsOwn":
219	                return contains(true);
220	            case "containsWholeText":
221	                return containsWholeText(false);
222	            case "containsWholeOwnText":
223	                return containsWholeText(true);
224	            case "containsData":
225	                return containsData();
226	            case "matches":
227	                return matches(false);
228	            case "matchesOwn":
229	                return matches(true);
230	            case "matchesWholeText":
231	                return matchesWholeText(false);
232	            case "matchesWholeOwnText":
233	                return matchesWholeText(true);
234	            case "not":
235	                return not();
236	            case "nth-child":
237	                return cssNthChild(false, false);
238	            case "nth-last-child":
239	                return cssNthChild(true, false);
240	            case "nth-of-type":
241	                return cssNthChild(false, true);
242	            case "nth-last-of-type":
243	                return cssNthChild(true, true);
244	            case "first-child":
245	                return new Evaluator.IsFirstChild();
246	            case "last-child":
247	                return new Evaluator.IsLastChild();
248	            case "first-of-type":
249	                return new Evaluator.IsFirstOfType();
250	            case "last-of-type":
251	                return new Evaluator.IsLastOfType();
252	            case "only-child":
253	                return new Evaluator.IsOnlyChild();
254	            case "only-of-type":
255	                return new Evaluator.IsOnlyOfType();
256	            case "empty":
257	                return new Evaluator.IsEmpty();
258	            case "blank":
259	                return new NodeEvaluator.BlankValue();
260	            case "root":
261	                return new Evaluator.IsRoot();
262	            case "matchText": {
263	                @SuppressWarnings("deprecation") // :matchText remains supported until its scheduled removal.
264	                Evaluator.MatchText matchText = new Evaluator.MatchText();
265	                return matchText;
266	            }
267	            default:
268	                throw new Selector.SelectorParseException("Could not parse query '%s': unexpected token at '%s'", query, tq.remainder());
269	        }
270	    }
271	
272	    // ::comment etc
273	    private Evaluator parseNodeSelector() {
274	        final String pseudo = tq.consumeCssIdentifier();
275	        inNodeContext = true;  // Enter node context
276	
277	        Evaluator left;
278	        switch (pseudo) {
279	            case "node":
280	                left = new NodeEvaluator.InstanceType(Node.class, pseudo);
281	                break;
282	            case "leafnode":
283	                left = new NodeEvaluator.InstanceType(LeafNode.class, pseudo);
284	                break;
285	            case "text":
286	                left = new NodeEvaluator.InstanceType(TextNode.class, pseudo);
287	                break;
288	            case "comment":
289	                left = new NodeEvaluator.InstanceType(Comment.class, pseudo);
290	                break;
291	            case "data":
292	                left = new NodeEvaluator.InstanceType(DataNode.class, pseudo);
293	                break;
294	            case "cdata":
295	                left = new NodeEvaluator.InstanceType(CDataNode.class, pseudo);
296	                break;
297	            default:
298	                throw new Selector.SelectorParseException(
299	                    "Could not parse query '%s': unknown node type '::%s'", query, pseudo);
300	        }
301	
302	        // Handle following subclasses in node context (like ::comment:contains())
303	        Evaluator right;
304	        while ((right = parseSubclass()) != null) {
305	            left = and(left, right);
306	        }
307	
308	        inNodeContext = false;
309	        return left;
310	    }
311	
312	    private Evaluator byId() {
313	        String id = tq.consumeCssIdentifier();
314	        Validate.notEmpty(id);
315	        return new Evaluator.Id(id);
316	    }
317	
318	    private Evaluator byClass() {
319	        String className = tq.consumeCssIdentifier();
320	        Validate.notEmpty(className);
321	        return new Evaluator.Class(className.trim());
322	    }
323	
324	    private Evaluator byTag() {
325	        // todo - these aren't dealing perfectly with case sensitivity. For case sensitive parsers, we should also make
326	        // the tag in the selector case-sensitive (and also attribute names). But for now, normalize (lower-case) for
327	        // consistency - both the selector and the element tag
328	        String tagName = normalize(tq.consumeElementSelector());
329	        Validate.notEmpty(tagName);
330	
331	        // namespaces:
332	        if (tagName.startsWith("*|")) { // namespaces: wildcard match equals(tagName) or ending in ":"+tagName
333	            String plainTag = tagName.substring(2); // strip *|
334	            return new CombiningEvaluator.Or(
335	                new Evaluator.Tag(plainTag),
336	                new Evaluator.TagEndsWith(":" + plainTag)
337	            );
338	        } else if (tagName.endsWith("|*")) { // ns|*
339	            String ns = tagName.substring(0, tagName.length() - 2) + ":"; // strip |*, to ns:
340	            return new Evaluator.TagStartsWith(ns);
341	        } else if (tagName.contains("|")) { // flip "abc|def" to "abc:def"
342	            tagName = tagName.replace("|", ":");
343	        }
344	
345	        return new Evaluator.Tag(tagName);
346	    }
347	
348	    private Evaluator byAttribute() {
349	        try (TokenQueue cq = new TokenQueue(tq.chompBalanced('[', ']'))) {
350	            return evaluatorForAttribute(cq);
351	        }
352	    }
353	
354	    private Evaluator evaluatorForAttribute(TokenQueue cq) {
355	        String key = cq.consumeToAny(AttributeEvals); // eq, not, start, end, contain, match, (no val)
356	        key = normalize(key);
357	        Validate.notEmpty(key);
358	        Validate.isFalse(key.equals("abs:"), "Absolute attribute key must have a name");
359	        cq.consumeWhitespace();
360	        final Evaluator eval;
361	
362	        if (cq.isEmpty()) {
363	            if (key.startsWith("^"))
364	                eval = new Evaluator.AttributeStarting(key.substring(1));
365	            else if (key.equals("*")) // any attribute
366	                eval = new Evaluator.AttributeStarting("");
367	            else
368	                eval = new Evaluator.Attribute(key);
369	        } else {
370	            if (cq.matchChomp('='))
371	                eval = new Evaluator.AttributeWithValue(key, cq.remainder());
372	            else if (cq.matchChomp("!="))
373	                eval = new Evaluator.AttributeWithValueNot(key, cq.remainder());
374	            else if (cq.matchChomp("^="))
375	                eval = new Evaluator.AttributeWithValueStarting(key, cq.remainder());
376	            else if (cq.matchChomp("$="))
377	                eval = new Evaluator.AttributeWithValueEnding(key, cq.remainder());
378	            else if (cq.matchChomp("*="))
379	                eval = new Evaluator.AttributeWithValueContaining(key, cq.remainder());
380	            else if (cq.matchChomp("~="))
381	                eval = new Evaluator.AttributeWithValueMatching(key, Regex.compile(cq.remainder()));
382	            else
383	                throw new Selector.SelectorParseException(
384	                    "Could not parse attribute query '%s': unexpected token at '%s'", query, cq.remainder());
385	        }
386	        return eval;
387	    }
