389	    //pseudo selectors :first-child, :last-child, :nth-child, ...
390	    private static final Pattern NthStepOffset = Pattern.compile("(([+-])?(\\d+)?)n(\\s*([+-])?\\s*\\d+)?", Pattern.CASE_INSENSITIVE);
391	    private static final Pattern NthOffset = Pattern.compile("([+-])?(\\d+)");
392	
393	    private Evaluator cssNthChild(boolean last, boolean ofType) {
394	        String arg = consumeParens(); // arg is like "odd", "-n+2", or "2 of .p", within nth-child(...)
395	
396	        // split off the optional Selectors L4 " of S" clause, if any
397	        int[] ofBounds = ofClauseBounds(arg);
398	        final String formula = normalize(ofBounds == null ? arg : arg.substring(0, ofBounds[0]));
399	        final String ofPart = ofBounds == null ? null : arg.substring(ofBounds[1]).trim();
400	
401	        if (ofPart != null && ofType)
402	            throw new Selector.SelectorParseException(
403	                "Could not parse query '%s': the :nth-%sof-type pseudo-class does not support the 'of S' selector",
404	                query, last ? "last-" : "");
405	
406	        final int step, offset;
407	        if ("odd".equals(formula)) {
408	            step = 2;
409	            offset = 1;
410	        } else if ("even".equals(formula)) {
411	            step = 2;
412	            offset = 0;
413	        } else {
414	            Matcher stepOffsetM, stepM;
415	            if ((stepOffsetM = NthStepOffset.matcher(formula)).matches()) {
416	                if (stepOffsetM.group(3) != null) // has digits, like 3n+2 or -3n+2
417	                    step = Integer.parseInt(stepOffsetM.group(1).replaceFirst("^\\+", ""));
418	                else // no digits, might be like n+2, or -n+2. if group(2) == "-", it’s -1;
419	                    step = "-".equals(stepOffsetM.group(2)) ? -1 : 1;
420	                offset =
421	                    stepOffsetM.group(4) != null ? Integer.parseInt(stepOffsetM.group(4).replaceFirst("^\\+", "")) : 0;
422	            } else if ((stepM = NthOffset.matcher(formula)).matches()) {
423	                step = 0;
424	                offset = Integer.parseInt(stepM.group().replaceFirst("^\\+", ""));
425	            } else {
426	                throw new Selector.SelectorParseException("Could not parse nth-index '%s': unexpected format", formula);
427	            }
428	        }
429	
430	        Evaluator filter = null;
431	        if (ofPart != null) {
432	            Validate.notEmpty(ofPart, ":nth-child(An+B of S) requires a selector after 'of'");
433	            filter = parse(ofPart); // a selector list, parsed by the same grammar (and validated in full)
434	        }
435	
436	        if (ofType)
437	            return last ? new Evaluator.IsNthLastOfType(step, offset) : new Evaluator.IsNthOfType(step, offset);
438	        return last
439	            ? new Evaluator.IsNthLastChild(step, offset, filter)
440	            : new Evaluator.IsNthChild(step, offset, filter);
441	    }
