443	    /**
444	     Finds the bounds of the optional top-level {@code  of S} clause in an nth-child argument. The {@code of} keyword is
445	     only recognized when it is outside of nested parens/brackets and quoted strings, so that an {@code of} nested inside
446	     the {@code S} selector (or inside a quoted attribute value) is not mistaken for the clause.
447	     @param arg the raw argument within nth-child( ... )
448	     @return {@code [formulaEnd exclusive, selectorStart inclusive]}, or {@code null} if there is no {@code of S} clause
449	     */
450	    private static int @Nullable [] ofClauseBounds(String arg) {
451	        int depth = 0;
452	        boolean inQuote = false;
453	        boolean escaped = false;
454	
455	        for (int i = 0; i < arg.length(); i++) {
456	            char c = arg.charAt(i);
457	            if (inQuote) {
458	                if (escaped) escaped = false;
459	                else if (c == '\\') escaped = true;
460	                else if (c == '\'' || c == '"') inQuote = false;
461	                continue;
462	            }
463	            if (c == '\'' || c == '"') { inQuote = true; continue; }
464	            if (c == '(' || c == '[' || c == '{') { depth++; continue; }
465	            if (c == ')' || c == ']' || c == '}') { depth--; continue; }
466	
467	            if (depth == 0 && arg.regionMatches(true, i, "of", 0, 2)
468	                && i > 0 && StringUtil.isWhitespace(arg.charAt(i - 1))
469	                && i + 2 < arg.length() && StringUtil.isWhitespace(arg.charAt(i + 2))) {
470	
471	                int formulaEnd = i - 1; // index of the whitespace delimiting the formula
472	                while (formulaEnd >= 0 && StringUtil.isWhitespace(arg.charAt(formulaEnd))) formulaEnd--;
473	
474	                int selectorStart = i + 3; // first char after the whitespace following "of"
475	                while (selectorStart < arg.length() && StringUtil.isWhitespace(arg.charAt(selectorStart))) selectorStart++;
476	
477	                if (formulaEnd >= 0 && selectorStart < arg.length())
478	                    return new int[] {formulaEnd + 1, selectorStart};
479	            }
480	        }
481	        return null;
482	    }
483	
484	    private String consumeParens() {
485	        return tq.chompBalanced('(', ')');
486	    }
487	
488	    private int consumeIndex() {
489	        String index = consumeParens().trim();
490	        Validate.isTrue(StringUtil.isNumeric(index), "Index must be numeric");
491	        return Integer.parseInt(index);
492	    }
