494	    // pseudo selector :has(el)
495	    private Evaluator has() {
496	        return parseNested(StructuralEvaluator.Has::new, ":has() must have a selector");
497	    }
498	
499	    // pseudo selector :is()
500	    private Evaluator is() {
501	        return parseNested(StructuralEvaluator.Is::new, ":is() must have a selector");
502	    }
503	
504	    private Evaluator parseNested(Function<Evaluator, Evaluator> func, String err) {
505	        Validate.isTrue(tq.matchChomp('('), err);
506	        Evaluator eval = parseSelectorGroup();
507	        Validate.isTrue(tq.matchChomp(')'), err);
508	        return func.apply(eval);
509	    }
