511	    // pseudo selector :contains(text), containsOwn(text)
512	    private Evaluator contains(boolean own) {
513	        String query = own ? ":containsOwn" : ":contains";
514	        String searchText = TokenQueue.unescape(consumeParens());
515	        Validate.notEmpty(searchText, query + "(text) query must not be empty");
516	
517	        if (inNodeContext)
518	            return new NodeEvaluator.ContainsValue(searchText);
519	
520	        return own
521	            ? new Evaluator.ContainsOwnText(searchText)
522	            : new Evaluator.ContainsText(searchText);
523	    }
524	
525	    private Evaluator containsWholeText(boolean own) {
526	        String query = own ? ":containsWholeOwnText" : ":containsWholeText";
527	        String searchText = TokenQueue.unescape(consumeParens());
528	        Validate.notEmpty(searchText, query + "(text) query must not be empty");
529	        return own
530	            ? new Evaluator.ContainsWholeOwnText(searchText)
531	            : new Evaluator.ContainsWholeText(searchText);
532	    }
533	
534	    // pseudo selector :containsData(data)
535	    private Evaluator containsData() {
536	        String searchText = TokenQueue.unescape(consumeParens());
537	        Validate.notEmpty(searchText, ":containsData(text) query must not be empty");
538	        return new Evaluator.ContainsData(searchText);
539	    }
