541	    // :matches(regex), matchesOwn(regex)
542	    private Evaluator matches(boolean own) {
543	        String query = own ? ":matchesOwn" : ":matches";
544	        String regex = consumeParens(); // don't unescape, as regex bits will be escaped
545	        Validate.notEmpty(regex, query + "(regex) query must not be empty");
546	        Regex pattern = Regex.compile(regex);
547	
548	        if (inNodeContext)
549	            return new NodeEvaluator.MatchesValue(pattern);
550	
551	        return own
552	            ? new Evaluator.MatchesOwn(pattern)
553	            : new Evaluator.Matches(pattern);
554	    }
555	
556	    // :matches(regex), matchesOwn(regex)
557	    private Evaluator matchesWholeText(boolean own) {
558	        String query = own ? ":matchesWholeOwnText" : ":matchesWholeText";
559	        String regex = consumeParens(); // don't unescape, as regex bits will be escaped
560	        Validate.notEmpty(regex, query + "(regex) query must not be empty");
561	
562	        Regex pattern = Regex.compile(regex);
563	        return own
564	            ? new Evaluator.MatchesWholeOwnText(pattern)
565	            : new Evaluator.MatchesWholeText(pattern);
566	    }
567	
568	    // :not(selector)
569	    private Evaluator not() {
570	        String subQuery = consumeParens();
571	        Validate.notEmpty(subQuery, ":not(selector) subselect must not be empty");
572	
573	        return new StructuralEvaluator.Not(parse(subQuery));
574	    }
