1	package org.jsoup.select;
2	
3	import org.jsoup.internal.SoftPool;
4	import org.jsoup.internal.StringUtil;
5	import org.jsoup.nodes.Element;
6	import org.jsoup.nodes.LeafNode;
7	import org.jsoup.nodes.Node;
8	import org.jsoup.nodes.NodeIterator;
9	import org.jsoup.nodes.TextNode;
10	
11	import java.util.ArrayList;
12	import java.util.Map;
13	import java.util.WeakHashMap;
14	
15	/**
16	 * Base structural evaluator.
17	 */
18	abstract class StructuralEvaluator extends Evaluator {
19	    final Evaluator evaluator;
20	    boolean wantsNodes; // if the evaluator requested nodes, not just elements
21	
22	    public StructuralEvaluator(Evaluator evaluator) {
23	        this.evaluator = evaluator;
24	        wantsNodes = evaluator.wantsNodes();
25	    }
26	
27	    @Override
28	    boolean wantsNodes() {
29	        return wantsNodes;
30	    }
31	
32	    // Memoize inner matches, to save repeated re-evaluations of parent, sibling etc.
33	    // root + element: Boolean matches. ThreadLocal in case the Evaluator is compiled then reused across multi threads
34	    final ThreadLocal<Map<Node, Map<Node, Boolean>>> threadMemo = ThreadLocal.withInitial(WeakHashMap::new);
35	
36	    boolean memoMatches(final Element root, final Node node) {
37	        Map<Node, Map<Node, Boolean>> rootMemo = threadMemo.get();
38	        Map<Node, Boolean> memo = rootMemo.computeIfAbsent(root, r -> new WeakHashMap<>());
39	        return memo.computeIfAbsent(node, test -> evaluator.matches(root, test));
40	    }
41	
42	    @Override protected void reset() {
43	        threadMemo.remove();
44	        evaluator.reset();
45	        super.reset();
46	    }
47	
48	    @Override
49	    public boolean matches(Element root, Element element) {
50	        return evaluateMatch(root, element);
51	    }
52	
53	    @Override
54	    boolean matches(Element root, LeafNode leafNode) {
55	        return evaluateMatch(root, leafNode);
56	    }
57	
58	    abstract boolean evaluateMatch(Element root, Node node);
59	
60	    static class Root extends Evaluator {
61	        @Override
62	        public boolean matches(Element root, Element element) {
63	            return root == element;
64	        }
65	
66	        @Override protected int cost() {
67	            return 1;
68	        }
69	
70	        @Override public String toString() {
71	            return ">";
72	        }
73	    }
74	
75	    /**
76	     * Implements the {@code :has(relative-selector-list)} structural pseudo-class. The current candidate element is the
77	     * <b>anchor</b>; each comma-separated branch is evaluated <i>relative to that anchor</i>, and the anchor never
78	     * drifts to its own ancestors or siblings while a branch is tested:
79	     * <ul>
80	     *   <li>a branch with no leading combinator matches only within the anchor's descendants;</li>
81	     *   <li>a branch beginning with {@code >} (encoded as an {@link ImmediateParentRun} from the synthetic {@link Root})
82	     *       is confined to direct element children and below;</li>
83	     *   <li>a branch beginning with {@code +} or {@code ~} (an immediate/general sibling evaluator whose left side is
84	     *       the synthetic {@link Root}) is evaluated against the anchor's following element siblings and their
85	     *       descendants only; non-element nodes never act as siblings.</li>
86	     * </ul>
87	     * The parsed evaluator tree is left intact; the axis of each branch is derived from whether its leading combinator
88	     * references the synthetic {@link Root}. Branches are ORed here, but the collector de-duplicates and orders results.
89	     */
90	    static class Has extends StructuralEvaluator {
91	        static final SoftPool<NodeIterator<Node>> NodeIterPool =
92	            new SoftPool<>(() -> new NodeIterator<>(new TextNode(""), Node.class));
93	        // the element here is just a placeholder so this can be final - gets set in restart()
94	
95	        private final Evaluator[] branches; // each comma-separated relative branch
96	        private final char[] axes;          // axis per branch: 0 = descendants, '+' / '~' = following element siblings
97	        private final boolean[] deep;       // sibling branches that chain a further combinator and so must search subtrees
98	
99	        public Has(Evaluator evaluator) {
100	            super(evaluator);
101	
102	            ArrayList<Evaluator> clauses = new ArrayList<>();
103	            if (evaluator instanceof CombiningEvaluator.Or) {
104	                clauses.addAll(((CombiningEvaluator.Or) evaluator).evaluators);
105	            } else {
106	                clauses.add(evaluator);
107	            }
108	            branches = clauses.toArray(new Evaluator[0]);
109	            axes = new char[branches.length];
110	            deep = new boolean[branches.length];
111	            for (int i = 0; i < branches.length; i++) {
112	                axes[i] = siblingAxis(branches[i]);
113	                deep[i] = axes[i] != 0 && hasChainedCombinator(branches[i]);
114	            }
115	        }
116	
117	        @Override public boolean matches(Element root, Element element) {
118	            for (int i = 0; i < branches.length; i++) {
119	                Evaluator branch = branches[i];
120	                if (axes[i] == 0) {
121	                    if (matchesDescendants(element, branch)) return true;
122	                } else {
123	                    if (matchesFollowingSiblings(element, axes[i], deep[i], branch)) return true;
124	                }
125	            }
126	            return false;
127	        }
128	
129	        /** Match a descendant-only branch (bare or {@code >}) within the anchor, never against the anchor itself. */
130	        private static boolean matchesDescendants(Element anchor, Evaluator branch) {
131	            NodeIterator<Node> it = NodeIterPool.borrow();
132	            it.restart(anchor);
133	            try {
134	                while (it.hasNext()) {
135	                    Node node = it.next();
136	                    if (node == anchor) continue; // don't match self, only descendants
137	                    if (branch.matches(anchor, node)) return true;
138	                }
139	            } finally {
140	                NodeIterPool.release(it);
141	            }
142	            return false;
143	        }
144	
145	        /**
146	         * Match a {@code +}/{@code ~} branch against following element siblings (element nodes only). The anchor is
147	         * supplied as the matching root, so the branch's leading sibling edge (whose left side is the synthetic Root)
148	         * resolves to the anchor: {@code +} is satisfied only by the immediate sibling, {@code ~} by any later one.
149	         * A simple branch ({@code + p.selected}) tests the sibling elements directly, with {@code +} stopping after the
150	         * first. A branch that chains further combinators ({@code + article > img}, {@code + p + img}, {@code ~ p span})
151	         * may match within a sibling's subtree, or -- with chained sibling combinators -- in a later sibling, so every
152	         * following sibling and its subtree is searched; the root-scoped structural evaluators enforce the exact
153	         * adjacency and never walk above the anchor, so the broader search domain cannot mis-match.
154	         */
155	        private static boolean matchesFollowingSiblings(Element anchor, char axis, boolean deep, Evaluator branch) {
156	            Element sibling = anchor.nextElementSibling();
157	            if (!deep) {
158	                while (sibling != null) {
159	                    if (branch.matches(anchor, sibling)) return true;
160	                    if (axis == '+') break; // '+' is the immediate sibling only; '~' may reach a later one
161	                    sibling = sibling.nextElementSibling();
162	                }
163	                return false;
164	            }
165	
166	            NodeIterator<Node> it = NodeIterPool.borrow();
167	            try {
168	                while (sibling != null) {
169	                    it.restart(sibling);
170	                    while (it.hasNext()) {
171	                        Node node = it.next();
172	                        if (branch.matches(anchor, node)) return true;
173	                    }
174	                    sibling = sibling.nextElementSibling();
175	                }
176	            } finally {
177	                NodeIterPool.release(it);
178	            }
179	            return false;
180	        }
181	
182	        @Override
183	        boolean evaluateMatch(Element root, Node node) {
184	            return false; // unused; :has(::comment)) goes via implicit root combinator
185	        }
186	
187	        /**
188	         * Determine a branch's leading sibling axis, if any, by tracing its left-most combinator edge. Only a leading
189	         * {@code +} or {@code ~} is compiled against the synthetic {@link Root} (the anchor): it appears as an
190	         * immediate/general sibling evaluator wrapping {@link Root} at the start of the chain (possibly beneath
191	         * descendant and child edges). An internal sibling combinator references a real selector, not {@link Root},
192	         * and so is scoped to the anchor's descendants rather than the anchor's own siblings.
193	         * @return {@code '+'}, {@code '~'}, or {@code 0} for a descendant-only branch
194	         */
195	        private static char siblingAxis(Evaluator branch) {
196	            Evaluator edge = branch;
197	            while (true) {
198	                if (edge instanceof CombiningEvaluator.And) {
199	                    // the parser places the left-hand structural wrapper (Ancestor/sibling) first in the And
200	                    edge = ((CombiningEvaluator.And) edge).evaluators.get(0);
201	                } else if (edge instanceof ImmediateParentRun) {
202	                    edge = ((ImmediateParentRun) edge).evaluators.get(0);
203	                } else if (edge instanceof Ancestor) {
204	                    edge = ((Ancestor) edge).evaluator;
205	                } else if (edge instanceof ImmediatePreviousSibling) {
206	                    Evaluator left = ((StructuralEvaluator) edge).evaluator;
207	                    if (left instanceof Root) return '+';
208	                    edge = left; // a chained sibling combinator; continue to the left-most edge
209	                } else if (edge instanceof PreviousSibling) {
210	                    Evaluator left = ((StructuralEvaluator) edge).evaluator;
211	                    if (left instanceof Root) return '~';
212	                    edge = left;
213	                } else {
214	                    return 0; // bare branch, or a leading '>' (a Root)
215	                }
216	            }
217	        }
218	
219	        /**
220	         * Whether a sibling branch chains a further combinator after its leading {@code +}/{@code ~}, such that the
221	         * match target may lie within a sibling's subtree (e.g. {@code + article > img}) rather than being the sibling
222	         * element itself (e.g. {@code + p.selected}). The leading sibling-of-{@link Root} edge is the axis edge and is
223	         * not counted; {@link Is}, {@link Not} and nested {@link Has} evaluate their own contents and are self-contained.
224	         */
225	        private static boolean hasChainedCombinator(Evaluator eval) {
226	            if (eval instanceof Ancestor) return true;
227	            if (eval instanceof ImmediateParentRun) return ((ImmediateParentRun) eval).evaluators.size() > 1;
228	            if (eval instanceof ImmediatePreviousSibling || eval instanceof PreviousSibling)
229	                return !(((StructuralEvaluator) eval).evaluator instanceof Root); // the leading axis edge wraps Root
230	            if (eval instanceof CombiningEvaluator) {
231	                for (Evaluator child : ((CombiningEvaluator) eval).evaluators) {
232	                    if (hasChainedCombinator(child)) return true;
233	                }
234	            }
235	            return false; // a plain simple sequence, or a self-contained evaluator (Is, Not, nested Has, etc.)
236	        }
237	
238	        @Override protected int cost() {
239	            return 10 * evaluator.cost();
240	        }
241	
242	        @Override
243	        public String toString() {
244	            return String.format(":has(%s)", evaluator);
245	        }
246	    }
247	
248	    /** Implements the :is(sub-query) pseudo-selector */
249	    static class Is extends StructuralEvaluator {
250	        public Is(Evaluator evaluator) {
251	            super(evaluator);
252	        }
253	
254	        @Override
255	        boolean evaluateMatch(Element root, Node node) {
256	            return evaluator.matches(root, node);
257	        }
258	
259	        @Override protected int cost() {
260	            return 2 + evaluator.cost();
261	        }
262	
263	        @Override
264	        public String toString() {
265	            return String.format(":is(%s)", evaluator);
266	        }
267	    }
268	
269	    static class Not extends StructuralEvaluator {
270	        public Not(Evaluator evaluator) {
271	            super(evaluator);
272	        }
273	
274	        @Override
275	        boolean evaluateMatch(Element root, Node node) {
276	            return !memoMatches(root, node);
277	        }
278	
279	        @Override protected int cost() {
280	            return 2 + evaluator.cost();
281	        }
282	
283	        @Override
284	        public String toString() {
285	            return String.format(":not(%s)", evaluator);
286	        }
287	    }
288	
289	    /**
290	     Any Ancestor (i.e., ascending parent chain.).
291	     */
292	    static class Ancestor extends StructuralEvaluator {
293	        public Ancestor(Evaluator evaluator) {
294	            super(evaluator);
295	        }
296	
297	        @Override
298	        boolean evaluateMatch(Element root, Node node) {
299	            if (root == node)
300	                return false;
301	
302	            for (Node parent = node.parent(); parent != null; parent = parent.parent()) {
303	                if (memoMatches(root, parent))
304	                    return true;
305	                if (parent == root)
306	                    break;
307	            }
308	            return false;
309	        }
310	
311	        @Override
312	        protected int cost() {
313	            return 8 * evaluator.cost(); // probably lower than has(), but still significant, depending on doc and el depth.
314	        }
315	
316	        @Override
317	        public String toString() {
318	            return String.format("%s ", evaluator);
319	        }
320	    }
321	
322	    /**
323	     Holds a list of evaluators for one > two > three immediate parent matches, and the final direct evaluator under
324	     test. To match, these are effectively ANDed together, starting from the last, matching up to the first.
325	     */
326	    static class ImmediateParentRun extends StructuralEvaluator {
327	        final ArrayList<Evaluator> evaluators = new ArrayList<>();
328	        int cost = 2;
329	
330	        public ImmediateParentRun(Evaluator evaluator) {
331	            super(evaluator);
332	            evaluators.add(evaluator);
333	            cost += evaluator.cost();
334	        }
335	
336	        void add(Evaluator evaluator) {
337	            evaluators.add(evaluator);
338	            cost += evaluator.cost();
339	            wantsNodes |= evaluator.wantsNodes();
340	        }
341	
342	        @Override boolean evaluateMatch(Element root, Node node) {
343	            if (node == root)
344	                return false; // cannot match as the second eval (first parent test) would be above the root
345	
346	            for (int i = evaluators.size() -1; i >= 0; --i) {
347	                if (node == null)
348	                    return false;
349	                Evaluator eval = evaluators.get(i);
350	                if (!eval.matches(root, node))
351	                    return false;
352	                node = node.parent();
353	            }
354	            return true;
355	        }
356	
357	        @Override protected int cost() {
358	            return cost;
359	        }
360	
361	        @Override
362	        protected void reset() {
363	            for (Evaluator evaluator : evaluators) {
364	                evaluator.reset();
365	            }
366	            super.reset();
367	        }
368	
369	        @Override
370	        public String toString() {
371	            return StringUtil.join(evaluators, " > ");
372	        }
373	    }
374	
375	    static class PreviousSibling extends StructuralEvaluator {
376	        public PreviousSibling(Evaluator evaluator) {
377	            super(evaluator);
378	        }
379	
380	        // matches any previous sibling, so can be same in Element only or wantsNodes context
381	        @Override boolean evaluateMatch(Element root, Node node) {
382	            if (root == node) return false;
383	
384	            for (Node sib = node.firstSibling(); sib != null; sib = sib.nextSibling()) {
385	                if (sib == node) break;
386	                if (memoMatches(root, sib)) return true;
387	            }
388	
389	            return false;
390	        }
391	
392	        @Override protected int cost() {
393	            return 3 * evaluator.cost();
394	        }
395	
396	        @Override
397	        public String toString() {
398	            return String.format("%s ~ ", evaluator);
399	        }
400	    }
401	
402	    static class ImmediatePreviousSibling extends StructuralEvaluator {
403	        public ImmediatePreviousSibling(Evaluator evaluator) {
404	            super(evaluator);
405	        }
406	
407	        @Override boolean evaluateMatch(Element root, Node node) {
408	            if (root == node) return false;
409	
410	            Node prev = wantsNodes ? node.previousSibling() : node.previousElementSibling();
411	            return prev != null && memoMatches(root, prev);
412	        }
413	
414	        @Override protected int cost() {
415	            return 2 + evaluator.cost();
416	        }
417	
418	        @Override
419	        public String toString() {
420	            return String.format("%s + ", evaluator);
421	        }
